import random


def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    my_score = 0
    opp_score = 0

    for i in range(n):
        me, opp = history[i]
        if me == 'C' and opp == 'C':
            my_score += 3
            opp_score += 3
        elif me == 'C' and opp == 'D':
            my_score += 0
            opp_score += 5
        elif me == 'D' and opp == 'C':
            my_score += 5
            opp_score += 0
        else:
            my_score += 1
            opp_score += 1

    opp_defects = 0
    recent_opp_defects = 0
    recent_n = min(n, 10)
    for i in range(n - recent_n, n):
        me, opp = history[i]
        if opp == 'D':
            opp_defects += 1
            recent_opp_defects += 1
        elif i >= n - recent_n:
            pass

    tail = history[-recent_n:]
    tail_c = sum(1 for a, b in tail if b == 'C')

    if n >= 4:
        last4 = history[-4:]
        if all(b == 'D' for a, b in last4):
            defections = 0
            for i in range(max(0, n - 20), n):
                if history[i][1] == 'D':
                    defections += 1
            if defections < 15:
                if rng.random() < 0.75:
                    return 'D'
                return 'C'
            return 'D' if rng.random() < 0.55 else 'C'

    if n >= 12:
        if tail_c <= 2:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        if tail_c >= 9:
            return 'C'

    total_defections = opp_defects
    cooperation_rate = (n - total_defections) / n

    if n < 8:
        if history[-1][1] == 'D':
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    if history[-1][1] == 'C':
        if cooperation_rate > 0.6 or rng.random() < 0.9:
            return 'C'
        return 'D'

    if cooperation_rate > 0.7:
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    if cooperation_rate < 0.35:
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    if rng.random() < 0.4:
        return 'D'
    return 'C'
